// Skill Galaxy — Digital Dock and Money Meteor questions.
// Questions written for Skill Galaxy; topics from the Marble Skill Taxonomy (CC BY-SA 4.0).
SG_Q({
  // ===================== DIGITAL DOCK =====================

  // Inside a computer
  "mt_GKL5Usnd11": [
    { q: "Which part of a computer carries out program instructions and does the calculations?", a: ["The processor (CPU)", "The storage", "The battery", "The wireless adaptor"], why: "The processor (CPU) is the part that follows program instructions and does the calculations. Storage keeps files; the battery supplies power." },
    { q: "In the desk-and-cupboard analogy, what is the memory (RAM) like?", a: ["The desk, holding things in use now", "The cupboard, keeping files for later", "The worker who does all the jobs", "The plug that brings in the power"], why: "Memory (RAM) holds the programs and data being used right now, like work spread out on a desk. Storage is the cupboard where files are kept for later." },
    { q: "Which part lets a tablet join Wi-Fi without a cable?", a: ["The wireless adaptor", "The processor", "The memory (RAM)", "The battery"], why: "The wireless adaptor sends and receives data using radio waves, so the device can join Wi-Fi or use Bluetooth without a cable." },
    { q: "Your laptop battery dies and it switches off before you saved your story. Why might your latest changes be lost?", a: ["They were only in RAM, which forgets without power", "The processor deleted them to save energy", "Storage always empties when the battery dies", "The wireless adaptor sent them away"], why: "RAM is temporary: it loses everything when the power goes. Saving copies your work to storage, which keeps it even when the device is off." },
    { q: "What is the job of the circuit board (motherboard)?", a: ["It links the parts so they can pass data", "It stores your photos and documents", "It does all the program's calculations", "It keeps the device charged up"], why: "The circuit board holds the parts and joins them with tiny metal tracks, so the processor, memory and storage can pass data and power to each other." },
    { q: "Sam's phone keeps saying 'Storage full' when he takes photos. Which feature of a new phone would help most?", a: ["More storage: 128 GB, not 64 GB", "More RAM: 8 GB, not 4 GB", "A faster processor chip", "A bigger, longer-lasting battery"], why: "Photos are saved in storage, so more storage means room for more files. More RAM helps with apps in use but does not hold saved photos." },
    { q: "Tablet A has 4 GB RAM and 256 GB storage. Tablet B has 8 GB RAM and 64 GB storage. Which is true?", a: ["A can hold more files; B can keep more apps open", "A can keep more apps open; B can hold more files", "B is better at everything because 8 is bigger", "They're equal because both are measured in GB"], why: "Storage (256 GB v 64 GB) decides how many files fit, so A holds more. RAM (8 GB v 4 GB) is working space for apps in use, so B copes better with lots open." },
    { q: "Mia says, 'RAM keeps my files safe when the computer is switched off.' What is wrong with this?", a: ["RAM is cleared when the power goes off", "RAM only stores music, not other files", "Files are kept safe by the battery", "Nothing — RAM keeps files for ever"], why: "RAM is fast but temporary, and it is wiped when the power goes off. Files are kept safe in storage (such as an SSD or hard drive) until you delete them." }
  ],

  // Computer networks
  "mt_Hft-0nxZvB": [
    { q: "What is a computer network?", a: ["Devices connected so they can share data", "A single computer with a big screen", "A program for drawing pictures", "A list of website addresses"], why: "A network is two or more devices linked by cable or wirelessly, so they can share data and resources such as printers and internet access." },
    { q: "In a home network, which device links the computers and phones together and to the internet?", a: ["The router", "The keyboard", "The monitor", "The speaker"], why: "The router passes data between devices on the home network, by cable or Wi-Fi, and connects the whole network to the internet." },
    { q: "Which of these is a **wireless** connection?", a: ["Bluetooth", "A USB cable", "An Ethernet cable", "An HDMI cable"], why: "Bluetooth uses radio waves to send data over short distances, with no cable. USB, Ethernet and HDMI all send data along wires." },
    { q: "On the same connection you send a short text, a photo and a 2-minute video. Which usually takes longest to send?", a: ["The 2-minute video", "The short text", "The photo", "They all take the same time"], why: "Larger files take longer to send. A video holds many pictures plus sound, so it is much bigger than a photo, and a photo is far bigger than a short text." },
    { q: "Why do schools connect their classroom computers into a network?", a: ["To share files, printers and the internet", "To make each battery last longer", "So computers never need any software", "So pupils never need to log in"], why: "A network lets devices share resources: one printer for a whole class, shared files on a server and one internet connection for everyone." },
    { q: "What does a server do on a school network?", a: ["Stores shared files and provides services", "Shows pictures on a classroom screen", "Turns typing into spoken words", "Charges the laptops overnight"], why: "A server is a computer that provides services to other devices on the network, such as storing shared files, checking logins or hosting web pages." },
    { q: "Ali prints a photo from his tablet over the home Wi-Fi network. Which path does the data most likely take?", a: ["Tablet → router → printer", "Printer → router → tablet", "Tablet → satellite → printer", "Tablet → USB stick → printer"], why: "On a home Wi-Fi network, the tablet sends the data by radio to the router, which passes it on to the printer by Wi-Fi or by cable." },
    { q: "Which is usually an advantage of a wired (cable) connection compared with Wi-Fi?", a: ["Speed and a steadier connection", "Freedom to walk around the house", "No need for plugs, sockets or cables", "Easier set-up on a new phone"], why: "Cables aren't affected by walls or interference, so they are often faster and steadier. Wi-Fi's big advantage is that you can move around." }
  ],

  // How the internet sends data
  "mt_el7qeUK-Cd": [
    { q: "Which is the best description of the internet?", a: ["A network of networks around the world", "One giant computer in America", "The same thing as a web browser", "A single cable between two countries"], why: "The internet links millions of smaller networks — in homes, schools and businesses — across the world, so they can all exchange data." },
    { q: "Before a photo is sent across the internet, what happens to it?", a: ["It is split into small packets", "It is sent whole, in one piece", "It is copied onto a memory stick", "It is printed out first"], why: "Data is broken into small chunks called packets. Each packet travels separately, and they are put back together at the other end." },
    { q: "Why is each packet given a number?", a: ["So they can be put back in the right order", "So they travel faster than other packets", "So the sender can pay for each one", "So they can never get lost"], why: "Packets may take different routes and arrive out of order. The numbers let the receiving computer rebuild the data correctly and spot missing ones." },
    { q: "As well as a piece of the data, what does each packet carry so it reaches the right place?", a: ["The address it is going to", "A copy of every other packet", "The sender's password", "A map of the whole internet"], why: "Each packet is labelled with the address it is going to (and where it came from), so routers can pass it along towards the right computer." },
    { q: "Two packets from the same message are sent at the same moment. Which is true?", a: ["They can travel by different routes", "They can only travel by the same route", "They can only arrive in the order sent", "They can't be sent until the other arrives"], why: "Routers send each packet along whichever route is best at that moment, so packets from one message can travel different ways and arrive out of order." },
    { q: "During a video call, the picture freezes for a moment, then carries on. What most likely happened?", a: ["Some packets were lost or arrived late", "The internet ran out of space for videos", "The whole internet shut down briefly", "The router deleted the video file"], why: "Live video needs packets to arrive quickly. If some are delayed or lost on the way, the picture freezes until enough data gets through again." },
    { q: "An email is split into packets numbered 1 to 5. Packets 1, 2, 4 and 5 arrive. What does the receiving computer do?", a: ["Asks for packet 3 to be sent again", "Shows the email without packet 3", "Puts packet 5 in the gap instead", "Deletes the email and gives up"], why: "The numbers show that packet 3 is missing, so the receiver asks for it to be resent. Then it can rebuild the whole email in the right order." },
    { q: "Why does the internet split data into packets instead of sending one big chunk?", a: ["Packets can share routes and be resent if lost", "Packets are secret so nobody can read them", "One big chunk would be too heavy for cables", "It squashes the file so it uses less data"], why: "Small packets can share busy routes with everyone else's data and take the best path, and only lost packets need resending — not the whole file." }
  ],

  // All data as numbers
  "mt_sHMpam8zcd": [
    { q: "How does a computer store a photo?", a: ["As numbers for the colour of each pixel", "As a tiny printed copy kept inside it", "As words that describe the picture", "As one number for the whole photo"], why: "A digital photo is a grid of pixels. Each pixel's colour is stored as numbers, so the whole photo is really a long list of numbers." },
    { q: "In a pixel code, 0 = white and 1 = black. Reading left to right, what does the row 1 1 0 0 show?", a: ["Two black squares, then two white", "Two white squares, then two black", "Black, white, black, white", "Four black squares in a row"], why: "Each number is one pixel: 1 is black and 0 is white. So 1 1 0 0 is black, black, white, white." },
    { q: "In ASCII code, A = 65, B = 66, C = 67 and so on. Which word is 67 65 66?", a: ["CAB", "BAC", "ACB", "CBA"], why: "67 is C, 65 is A and 66 is B, so 67 65 66 spells CAB." },
    { q: "In ASCII code, A = 65, B = 66, C = 67 and so on. What number is the letter E?", a: ["69", "68", "70", "5"], why: "The codes go up by one for each letter: A 65, B 66, C 67, D 68, E 69. E is the 5th letter, but its code is 69, not 5." },
    { q: "How is sound stored in a digital device?", a: ["As lots of number samples of the sound", "As a single number for the whole song", "As a tiny vinyl record inside the device", "As letters spelling out all the words"], why: "The device measures the sound wave thousands of times every second. Each measurement, called a sample, is stored as a number." },
    { q: "A screen mixes red, green and blue light. A pixel stored as (255, 255, 0) has full red, full green and no blue. What colour does it show?", a: ["Yellow", "Brown", "Orange", "White"], why: "Mixing red and green **light** makes yellow. Light doesn't mix like paint, which would give brown. Adding full blue as well, (255, 255, 255), would make white." },
    { q: "Jay says, 'My phone stores text as numbers, but photos and music are stored in a different way.' What is wrong?", a: ["Photos and music are stored as numbers too", "Text is stored as pictures, not numbers", "Only music is stored as numbers", "Nothing — Jay is completely right"], why: "Everything in a digital device is numbers: letters have number codes, pixels have colour numbers and sound is a list of number samples." },
    { q: "Why does a photo with more pixels usually take up more storage space?", a: ["Each extra pixel needs more numbers stored", "More pixels make the colours brighter", "The camera adds a longer file name", "Photos with more pixels are heavier"], why: "Every pixel's colour is stored as numbers, so more pixels means more numbers to store and a bigger file." }
  ],

  // Binary on and off
  "mt_WQiVj8gIRs": [
    { q: "What is a single 1 or 0 in binary called?", a: ["A bit", "A byte", "A pixel", "A packet"], why: "A bit (short for binary digit) is a single 1 or 0, like one switch that is on or off. Eight bits make a byte." },
    { q: "Why do computers use binary (1s and 0s)?", a: ["Their switches have two states: on or off", "Binary numbers are shorter to write down", "Computers aren't able to count past ten", "So nobody else is able to read the data"], why: "Inside a computer, millions of tiny switches are either on (1) or off (0). Two states are easy to store and to tell apart reliably." },
    { q: "Binary place values go 8, 4, 2, 1. What is the binary number 1010 as an ordinary number?", a: ["10", "1,010", "5", "12"], why: "1010 means one 8, no 4, one 2 and no 1: 8 + 2 = 10." },
    { q: "Using binary cards worth 16, 8, 4, 2 and 1, which cards are face up to show 13?", a: ["8, 4 and 1", "8, 4 and 2", "16 and 1", "4, 2 and 1"], why: "13 = 8 + 4 + 1, so those three cards are face up (1) and the 16 and 2 are face down (0). In binary that is 01101." },
    { q: "Binary place values go 16, 8, 4, 2, 1. What is 10011 in binary as an ordinary number?", a: ["19", "13", "11", "35"], why: "10011 means one 16, no 8, no 4, one 2 and one 1: 16 + 2 + 1 = 19." },
    { q: "How is the number 6 written in binary?", a: ["110", "011", "101", "111"], why: "6 = 4 + 2. With place values 4, 2, 1 that is one 4, one 2 and no 1s: 110. (011 is 3, because the biggest value goes on the left.)" },
    { q: "With five binary cards worth 16, 8, 4, 2 and 1, what is the largest number you can show?", a: ["31", "16", "32", "5"], why: "Turn all five cards face up: 16 + 8 + 4 + 2 + 1 = 31. Counting 0 as well, five cards can show 32 different numbers (0 to 31)." },
    { q: "A code uses 1 = A, 2 = B, 3 = C and so on, with each number written as 5-bit binary. Which letter is 00011?", a: ["C", "A", "B", "K"], why: "00011 = 2 + 1 = 3, and 3 stands for C in this code. (Reading 11 as eleven, which would give K, forgets that it's binary.)" }
  ],

  // Decisions and input in programs
  "mt_nfGAtwqSvP": [
    { q: "Which block lets a program choose between two different actions?", a: ["if … then … else", "repeat 10", "move 10 steps", "set score to 0"], why: "An if … then … else block checks a condition: if it is true, the program does one thing; otherwise it does the other." },
    { q: "Which of these is an **input** to a program?", a: ["Pressing the right arrow key", "A sprite saying 'Hello!'", "A sound playing", "The sprite changing colour"], why: "An input is information going into a program, such as a key press, a mouse click, a sensor reading or a typed answer. The others are outputs." },
    { q: "A quiz asks 'What is 3 × 4?' then runs: if answer = 12 then say 'Correct' else say 'Try again'. The player types 13. What happens?", a: ["The sprite says 'Try again'", "The sprite says 'Correct'", "The sprite says both messages", "Nothing happens at all"], why: "13 is not equal to 12, so the condition is false and the else part runs: the sprite says 'Try again'." },
    { q: "A game runs: if score > 5 then say 'Level up!'. Which score makes the sprite say 'Level up!'?", a: ["6", "5", "4", "0"], why: "> means 'greater than'. 6 is greater than 5, but 5 is not greater than itself, so only 6 makes the condition true." },
    { q: "You want a sprite to move right when the right arrow key is pressed. Which code does this?", a: ["if key right arrow pressed then change x by 10", "if key right arrow pressed then change x by -10", "if key left arrow pressed then change x by 10", "if touching edge then change x by 10"], why: "The condition checks for the right arrow key, then increasing x by 10 moves the sprite right. Changing x by -10 would move it left." },
    { q: "A maze game uses: if touching colour red then go back to start. Which part is the condition?", a: ["touching colour red", "go back to start", "the maze background", "the arrow keys"], why: "The condition is the question the program checks: 'Is the sprite touching red?'. 'Go back to start' is the action that happens when it is true." },
    { q: "Ella wants 'Well done!' when the score is 10 or more. She writes: if score > 10 then say 'Well done!'. What's the problem?", a: ["A score of exactly 10 won't trigger it", "A score of 9 will trigger it by mistake", "It needs a repeat block to work", "Scores can't be used in conditions"], why: "score > 10 is only true for scores above 10. For whole-number scores she could use score > 9, which is true for 10 and above." },
    { q: "A program asks your age, then runs: if answer < 10 then say 'Junior' else say 'Senior'. Sam types 10. What is said?", a: ["Senior", "Junior", "Both Junior and Senior", "Nothing at all"], why: "< means 'less than'. 10 is not less than 10, so the condition is false and the else part runs: 'Senior'." }
  ],

  // Loops in programs
  "mt_6XbAmdmjDb": [
    { q: "Which loop does exactly the same as: move 10, move 10, move 10, move 10?", a: ["repeat 4 [move 10]", "repeat 10 [move 10]", "repeat 4 [move 40]", "forever [move 10]"], why: "The same block is used 4 times in a row, so a repeat 4 loop with move 10 inside does exactly the same job with fewer blocks." },
    { q: "What does a 'forever' loop do?", a: ["Repeats its blocks until the program stops", "Runs its blocks once, then stops", "Repeats its blocks exactly 10 times", "Waits for ever without doing anything"], why: "A forever loop repeats the blocks inside it again and again until the program is stopped — handy for things like checking keys in a game." },
    { q: "What shape does this draw: repeat 4 [move 100, turn right 90]?", a: ["A square", "A triangle", "A straight line", "A circle"], why: "It draws 4 equal sides and turns 90° after each one. Four equal sides with right-angle turns make a square." },
    { q: "A quiz should keep asking a question until the player gets it right. Which loop fits best?", a: ["A 'repeat until' loop", "A 'repeat 3' loop", "A 'repeat 1' loop", "A 'repeat 10' loop"], why: "'Repeat until' keeps going until a condition becomes true — here, until the right answer is given. 'Repeat 3' would stop after 3 tries even if still wrong." },
    { q: "Why is repeat 4 [move 10, turn 90] better than writing those two blocks out four times?", a: ["It's shorter, and easier to read and change", "It makes the sprite move further", "It makes the sprite turn the other way", "It's the only way a computer understands"], why: "Both versions do the same thing, but the loop uses fewer blocks, so it is quicker to write, easier to read, and you change one number to edit it." },
    { q: "How many times does the sprite say Hi in: repeat 3 [ repeat 2 [say Hi] ]?", a: ["6", "5", "3", "2"], why: "The inner loop says Hi twice, and the outer loop runs the inner loop 3 times: 3 × 2 = 6." },
    { q: "Zoe wants an equal-sided triangle and writes: repeat 3 [move 100, turn right 90]. What's wrong?", a: ["Each turn should be 120°, not 90°", "It should repeat 4 times, not 3", "Each move should be 90, not 100", "A triangle can't be drawn with a loop"], why: "To draw an equal-sided triangle the sprite must turn 120° at each corner (360° ÷ 3). Turning 90° three times leaves an open shape." },
    { q: "When does the loop 'repeat until score = 5' stop repeating?", a: ["When the score becomes 5", "After exactly 5 goes", "Never — it runs for ever", "As soon as the score is 0"], why: "'Repeat until' checks its condition each time round and stops as soon as it is true — here when the score reaches 5, however many goes that takes." }
  ],

  // Variables in programs
  "mt_YZOjP8KHsM": [
    { q: "What is a variable in a program?", a: ["A named store for a value that can change", "A block that repeats actions over and over", "A picture used as the sprite's costume", "A sound effect that the program plays"], why: "A variable is like a labelled box holding a value, such as a score or a name. The program can read it and change it while it runs." },
    { q: "A game sets score to 0, then changes score by 1 each time you catch a star. You catch 4 stars. What is score now?", a: ["4", "1", "0", "5"], why: "Score starts at 0 and goes up by 1 four times: 0 + 1 + 1 + 1 + 1 = 4." },
    { q: "A program stores your typed name in a variable called **name**, then says join 'Hello ' and name. Priya types Priya. What does it say?", a: ["Hello Priya", "Hello name", "Hello", "Priya Hello"], why: "The variable called name holds the value Priya, so join puts that value after 'Hello '. It shows what the variable holds, not its label." },
    { q: "A game uses: if lives = 0 then say 'Game over'. Lives starts at 3 and goes down by 1 at each crash. After how many crashes does the game end?", a: ["3", "2", "4", "1"], why: "Lives goes 3 → 2 → 1 → 0. After the 3rd crash, lives = 0, so the condition is true and 'Game over' appears." },
    { q: "Why do games keep the score in a variable instead of a fixed number?", a: ["The score needs to change as you play", "Variables make the game run faster", "Fixed numbers can't be shown on screen", "A variable keeps the score secret"], why: "A fixed number never changes. A variable can be updated each time something happens, so it keeps track of the score during the game." },
    { q: "Trace this: set x to 5, change x by 3, set x to x × 2. What is x at the end?", a: ["16", "13", "10", "11"], why: "x starts at 5, then changes by 3 to make 8, then is set to 8 × 2 = 16." },
    { q: "Max's game should start each round with the score at 0, but it keeps the old total. What did he most likely forget?", a: ["To set score to 0 at the start", "To change score by 1 when scoring", "To add a forever loop", "To give the sprite a costume"], why: "A variable keeps its last value until it is changed. Putting 'set score to 0' at the start of each round resets it." },
    { q: "A timer variable starts at 30 and changes by -1 every second. What does it hold after 10 seconds?", a: ["20", "40", "10", "29"], why: "Changing by -1 takes 1 away each second. After 10 seconds: 30 − 10 = 20." }
  ],

  // Strong, memorable passwords
  "mt_y8-x0P5P9R": [
    { q: "Which of these passwords is the strongest?", a: ["violin-cactus-ocean-ladder", "Password1234567890!", "BenjaminSmith-15-06-2015", "qwertyuiopasdfghjklzxc"], why: "Four random words make a long passphrase that's hard to guess. The others are long too, but use a common word, a name and birthday, or a row of keyboard keys." },
    { q: "Why is 'ben2015' a weak password?", a: ["It's a name and a year others could guess", "It's too long to remember easily", "Passwords must never contain numbers", "It needs to be written in capitals"], why: "Names, birthdays and years are easy for people who know you — or a guessing program — to work out. Random words are much safer." },
    { q: "A good password should be…", a: ["Easy for you to remember, hard to guess", "Hard for you to remember, easy to guess", "Your pet's name, so you never forget", "The same one you use for everything"], why: "You need to remember it without writing it where others can see, but nobody else should be able to guess it. Random words do both." },
    { q: "Which is the best way to make a strong passphrase?", a: ["Join three or four random words", "Use your name and your birthday", "Use one long dictionary word", "Type a row of keys, like qwerty"], why: "Random words joined together make a long password with a huge number of possibilities to try, but they're still easy to picture and remember." },
    { q: "Mia's password is 'elephant'. It's quite a long word. Is it a strong password?", a: ["No — single words are guessed quickly", "Yes — over 6 letters is always strong", "Yes — animal names are hard to guess", "No — passwords can't contain animals"], why: "Guessing programs try every dictionary word first, so one word — even a long one — is weak. Joining several random words is much stronger." },
    { q: "Your best friend asks for your game password so they can help you level up. What should you do?", a: ["Keep it private, even from friends", "Share it, because they're your friend", "Share it, then change it next year", "Write it on a note in your pencil case"], why: "Passwords are just for you (and a parent or carer). Even good friends can slip up or fall out, so keep it private and ask an adult if unsure." },
    { q: "Why does a longer passphrase make it harder for someone to guess?", a: ["There are far more possible combinations", "Long passwords are hidden from hackers", "Computers can't read long passwords", "Websites delete short passwords"], why: "Every extra random word or character multiplies the number of possibilities a guesser has to try, so long random passphrases are very hard to crack." },
    { q: "Leo makes his password 'Leo-Leo-Leo-Leo'. It's long, so what's the problem?", a: ["It repeats his name, an easy pattern", "It's too long for websites to accept", "It needs to be all capital letters", "Hyphens aren't allowed in passwords"], why: "Length only helps if the words are random. Repeating your own name is a simple pattern that guessers try early on." }
  ],

  // My digital footprint
  "mt_0XHRJ49akv": [
    { q: "What is your digital footprint?", a: ["The trail of information you leave online", "The marks your fingers leave on a screen", "A list of the apps on your phone", "Your password for a website"], why: "Your digital footprint is everything recorded about you online — posts, photos, comments, searches, game scores and data that apps collect." },
    { q: "Which of these adds to your digital footprint?", a: ["Searching for a recipe online", "Reading a paper book", "Writing a diary with a pen", "Drawing a picture with pencils"], why: "Online searches can be recorded by the website, so they become part of your digital footprint. The other activities happen offline." },
    { q: "You delete a post you regret. Which is true?", a: ["Someone may have already copied or shared it", "It's gone from the internet for ever", "Nobody could have seen it in that time", "Deleting it removes every screenshot too"], why: "Once something is posted, others can screenshot, copy or share it, and services may keep backups. Deleting doesn't guarantee it has gone." },
    { q: "Your aunt posts a photo of you on her social media. Is it part of your digital footprint?", a: ["Yes — what others post about you counts", "No — only things you post yourself count", "No — photos never count, only words", "Only if you press 'like' on the photo"], why: "Your footprint includes anything about you online, even if someone else posted it. It's fine to ask family to check with you first." },
    { q: "Before posting a comment, which question is the most useful to ask yourself?", a: ["Would I mind anyone seeing this in 5 years?", "Will this get lots of likes before bedtime?", "Is it short enough to fit on the screen?", "Can I just delete it later if I regret it?"], why: "Posts can last and spread. Thinking about who might see it in future — a teacher, a family member, a future employer — helps you decide wisely." },
    { q: "A free game app asks to see your location and contacts. What is a sensible first step?", a: ["Ask an adult; say no if it isn't needed", "Allow everything so the game runs faster", "Allow it — free apps never collect data", "Type in a friend's details instead"], why: "Apps can collect data that adds to your footprint. If a game doesn't need your location or contacts, it's safer to say no — check with an adult." },
    { q: "Which part of your digital footprint can build up without you posting anything?", a: ["Searches and taps recorded by apps", "A photo you upload to share", "A comment you write on a video", "A message you post in a group chat"], why: "Apps and websites can record things like searches, clicks, location and time spent. This footprint builds up even if you never post." },
    { q: "Ruby says, 'My account is private, so nothing I post can ever be seen by strangers.' What's the flaw?", a: ["Friends can screenshot and share her posts", "Private accounts are visible to everyone", "Private accounts delete posts after a day", "Nothing — private posts can never spread"], why: "Privacy settings help, but anyone who can see a post can copy or screenshot it and pass it on, so it may still reach people she didn't choose." }
  ],

  // Bias in AI systems
  "mt__BbOjiY5A5": [
    { q: "How does an AI system learn to do a task, such as recognising cats in photos?", a: ["It is trained on lots of example data", "It is born already knowing about cats", "It asks a cat expert every single time", "It keeps guessing at random for ever"], why: "AI systems learn patterns from training data — for example, thousands of labelled photos of cats. What they learn depends on what they are shown." },
    { q: "What does it mean if an AI system is 'biased'?", a: ["It works unfairly or worse for some groups", "It is switched off at night", "It works exactly the same for everyone", "It is faster than other AI systems"], why: "A biased AI gives results that are unfairly tilted — it works better for some people or groups than others, often without anyone meaning it to." },
    { q: "A face-recognition system was trained mostly on photos of people with light skin. What is likely to happen?", a: ["It works less well for people with darker skin", "It works equally well for everyone", "It only works on cartoon faces", "It works better for people with darker skin"], why: "It learned mainly from light-skinned faces, so it saw fewer examples of darker skin and makes more mistakes with them. Real systems have had this problem." },
    { q: "Where does bias in AI systems most often come from?", a: ["The data the AI was trained on", "The colour of the computer's case", "The speed of the internet", "The size of the screen it uses"], why: "AI copies patterns in its training data. If the data leaves some groups out, or reflects unfair ideas from the past, the AI repeats them." },
    { q: "Translating from a language with no separate words for 'he' and 'she', an app writes 'He is a doctor. She is a nurse.' Why?", a: ["Its training text often linked jobs that way", "The app is just choosing the words at random", "The app has found out who the people are", "The computer has its own opinions on jobs"], why: "The app learned from lots of text where 'doctor' often went with 'he' and 'nurse' with 'she', so it copied that pattern — a bias, not a fact." },
    { q: "Which is a good way to reduce bias in an AI system?", a: ["Train and test it with data from many groups", "Give it less training data to learn from", "Only test it on the people who built it", "Make the AI run faster"], why: "Using more varied data, and testing how well the AI works for different groups, helps people spot and fix unfair results before others rely on it." },
    { q: "An AI sorts job applications by learning from a company's past hires, who were nearly all men. What might go wrong?", a: ["It may unfairly favour male applicants", "It will choose people completely fairly", "It may unfairly favour female applicants", "It will refuse to pick anyone at all"], why: "The AI learns what past hires looked like and copies that pattern, so it may unfairly score women lower. A real company found this problem." },
    { q: "Omar says, 'AI is a computer, so it can't be unfair — computers just use facts.' What's wrong with this?", a: ["AI can copy unfair patterns from its data", "Computers always make up their answers", "AI can never be used for real jobs", "Nothing — computers are always fair"], why: "AI learns from data made by people, which can be incomplete or unfair. It follows the patterns it was given, so its results can be biased." }
  ],

  // ===================== MONEY METEOR =====================

  // How the economy works
  "mt_udgPy5oAvR": [
    { q: "What is a consumer?", a: ["Someone who buys goods and services", "Someone who makes goods to sell", "A shop that sells food and drink", "A machine that works in a factory"], why: "Consumers buy and use things; producers make goods or provide services. Most people are both — a baker buys flour and sells bread." },
    { q: "Which of these is a producer?", a: ["A farmer who grows and sells apples", "A child buying an ice lolly", "A family watching a film at home", "A shopper choosing a new coat"], why: "A producer makes goods or provides services to sell. The farmer grows apples; the others are consumers buying or using things." },
    { q: "What does 'demand' mean?", a: ["How much people want to buy something", "How much of something has been made", "The price printed on the label", "How many shops there are in a town"], why: "Demand is how much of something people want to buy. Supply is how much of it is available to sell." },
    { q: "What is an economy?", a: ["How a place makes, sells and buys things", "Only the money that banks keep", "A shop that only sells cheap things", "The list of prices in a supermarket"], why: "An economy is all the making, buying, selling and working that goes on in a place, such as a town or a whole country like the UK." },
    { q: "On a very hot day, lots of people want ice cream but the van has only a few left. What might happen to the price?", a: ["It's likely to go up", "It's likely to go down", "It will become free", "It can never change"], why: "When demand (how much people want) is high and supply (how much there is) is low, sellers can charge more. That's supply and demand." },
    { q: "A farm has a huge strawberry harvest and the shops are full of strawberries. What usually happens to the price?", a: ["It usually falls", "It usually rises", "It doubles every day", "Strawberries stop being sold"], why: "When supply is high, sellers compete to sell the fruit before it goes off, so prices tend to drop." },
    { q: "A new toy goes viral and every child wants one, but the factory can't make enough. What is likely to happen?", a: ["Prices rise and it's hard to find", "Prices fall because it's popular", "The factory stops making it", "Shops give it away for free"], why: "High demand plus limited supply means shoppers compete for the few available, so prices rise — especially second-hand — and shops sell out." },
    { q: "Why might the price of bread rise even when people want the same amount as before?", a: ["A poor harvest made wheat cost more", "Fewer people wanted to buy bread", "New bakeries opened in every street", "Shops had too much bread left over"], why: "If a poor harvest makes wheat scarce, bread costs more to make. Bakers pass the higher cost on, so the price goes up." }
  ],

  // Taxes & public services
  "mt_cSz7XTxVAx": [
    { q: "What is tax?", a: ["Money paid to the government to fund services", "A fee charged for opening a bank account", "Money the government pays to big shops", "A special kind of savings account"], why: "Taxes are payments that people and businesses must make to the government. The money pays for public services that everyone can use." },
    { q: "Which of these is paid for mainly by taxes in the UK?", a: ["State schools", "Cinema tickets", "Computer games", "Takeaway pizzas"], why: "State schools, the NHS, the police, the fire service and roads are paid for mostly from taxes. Cinema tickets and games are bought by individuals." },
    { q: "Why do people pay taxes?", a: ["Everyone chips in so everyone can use services", "So the government can make a profit", "Taxes are a punishment for earning money", "So that shops can keep their prices low"], why: "Tax pools money from lots of people to pay for things we all need — like hospitals, roads and the fire service — that would be hard to pay for alone." },
    { q: "A game costs £10 before VAT. VAT at 20% is added. What is the final price?", a: ["£12", "£10.20", "£8", "£30"], why: "20% of £10 is £2, and £10 + £2 = £12. VAT is a tax added to the price of many goods and services." },
    { q: "Which tax is usually taken from people's wages when they work?", a: ["Income Tax", "VAT", "Council Tax", "Road tax"], why: "Income Tax (along with National Insurance) is taken from the money people earn. VAT is added when you buy things; Council Tax is paid on homes." },
    { q: "Bin collections, libraries and street lights are run by your local council. Which tax do households pay to the council?", a: ["Council Tax", "VAT", "Income Tax", "National Insurance"], why: "Households pay Council Tax to their local council. It helps pay for local services like bin collections, libraries and street lighting." },
    { q: "Who decides how tax money is spent on things like the NHS and schools?", a: ["The government, which voters elect", "Each taxpayer picks their own service", "The banks that hold the money", "Hospitals and schools decide themselves"], why: "The government (and local councils, for local services) decides how to spend tax money. Voters choose who runs them at elections." },
    { q: "Nina says, 'Children don't pay any tax because they don't have jobs.' What's wrong with this?", a: ["They pay VAT on many things they buy", "Children pay Income Tax on pocket money", "Children pay Council Tax on bedrooms", "Nothing — children never pay any tax"], why: "VAT is included in the price of many things, such as toys and games, so anyone who buys them — even a child — pays some tax." }
  ],

  // Financial planning
  "mt_r1hw-KenpK": [
    { q: "Ava saves £5 every week for a bike that costs £60. How many weeks will it take her?", a: ["12 weeks", "10 weeks", "6 weeks", "15 weeks"], why: "Divide the cost by the weekly saving: £60 ÷ £5 = 12 weeks." },
    { q: "What is a savings goal?", a: ["Something you plan to save up money for", "Money that you have already spent", "A prize for scoring a goal at football", "The amount that a shop charges you"], why: "A savings goal is a target, such as a £60 bike, that you save towards. Knowing the cost and when you want it helps you plan how much to put aside." },
    { q: "Jo plans a £30 birthday party: £12 on pizza and £8 on cake. How much is left for decorations?", a: ["£10", "£20", "£12", "£50"], why: "£12 + £8 = £20 is spent, so £30 − £20 = £10 is left for decorations." },
    { q: "Why is it better to plan your pocket money than spend it all as soon as you get it?", a: ["You can afford bigger things you really want", "Money loses all its value after a week", "Planning means you never need to save", "Spending at once always gets better prices"], why: "Planning lets you set money aside for goals, so you can afford something bigger later instead of lots of small things you may not really want." },
    { q: "Which is a 'need' rather than a 'want' when planning a budget for a school trip?", a: ["The coach fare to get there", "A souvenir keyring", "Sweets for the journey", "An extra go at the arcade"], why: "A need is something you must have — you can't go without the coach fare. Souvenirs and sweets are wants: nice but optional, so they come after needs." },
    { q: "Leo gets £8 a week. He wants a £40 game in 5 weeks, but he spends £2 a week on snacks. Will he have enough?", a: ["No — he'll have £30, so £10 short", "Yes — he'll have exactly the £40", "Yes — he'll have £50, with £10 spare", "No — he'll have only £20, so £20 short"], why: "He saves £8 − £2 = £6 a week. In 5 weeks that's 5 × £6 = £30, which is £10 short of £40." },
    { q: "Ella saves £3 every week for a whole year (52 weeks). How much does she save altogether?", a: ["£156", "£36", "£150", "£52"], why: "£3 × 52 = £156. Small amounts saved regularly add up. (£36 would be £3 a month for 12 months.)" },
    { q: "Sam wants £90 trainers in 10 weeks' time and already has £20. How much must he save each week?", a: ["£7", "£9", "£2", "£11"], why: "He still needs £90 − £20 = £70. Spread over 10 weeks, that is £70 ÷ 10 = £7 a week." }
  ],

  // Comparing best buys
  "mt_Qe2PsFmSAH": [
    { q: "A pack of 4 yoghurts costs £2. What is the price per yoghurt?", a: ["50p", "£2", "25p", "£8"], why: "Divide the price by the number of items: £2 ÷ 4 = 50p each. This is the unit price." },
    { q: "What does a 'unit price' tell you?", a: ["The cost per item or per amount, e.g. 100 g", "The total price you pay for the whole pack", "How many items there are inside the pack", "The price the shop paid the supplier"], why: "Unit prices let you compare different pack sizes fairly by showing what you pay for the same amount — one item, 1 kg or 100 g, say." },
    { q: "Pens cost 30p each, or £2.50 for a pack of 10. Which is cheaper per pen?", a: ["The pack: 25p per pen", "Single pens: 30p each", "They cost the same", "The pack: 20p per pen"], why: "£2.50 ÷ 10 = 25p per pen, which is 5p less than buying single pens at 30p each." },
    { q: "Which is better value: a 2 kg bag of rice for £5.80, or a 500 g bag for £1.60?", a: ["The 2 kg bag for £5.80", "The 500 g bag for £1.60", "They are exactly the same value", "You can't compare different sizes"], why: "2 kg is the same as four 500 g bags. Four small bags cost 4 × £1.60 = £6.40, which is more than £5.80, so the 2 kg bag is better value." },
    { q: "Cereal A is 500 g for £2.50. Cereal B is 750 g for £3.30. Which is cheaper per 100 g?", a: ["B, at 44p per 100 g", "A, at 50p per 100 g", "Both cost 50p per 100 g", "A, because the box costs less"], why: "A: £2.50 ÷ 5 = 50p per 100 g. B: £3.30 ÷ 7.5 = 44p per 100 g. B is cheaper per 100 g, even though the box costs more." },
    { q: "A 2 kg bag of apples is cheaper per kg than a small bag, but Tom lives alone and eats one apple a week. Why might the small bag be better?", a: ["He'd likely throw many away uneaten", "Small bags always have a lower unit price", "Big bags always cost more per kilogram", "Apples in big bags are a different kind"], why: "A low unit price only helps if you use it all. If half the apples go off, Tom pays for food he never eats, so the small bag can work out cheaper." },
    { q: "Juice costs £1.20 for 1 litre or £1.65 for 1.5 litres. Which is better value?", a: ["1.5 litres, at £1.10 per litre", "1 litre, at £1.20 per litre", "1.5 litres, at £1.65 per litre", "They are exactly equal value"], why: "£1.65 ÷ 1.5 = £1.10 per litre, which is 10p less than £1.20 per litre, so the 1.5 litre bottle is better value." },
    { q: "Max says a 6-pack of cans for £3 must be better value than single cans at 45p, because multipacks are always cheaper. What's his mistake?", a: ["The pack is 50p a can, so singles are cheaper", "He's right — multipacks are always cheaper", "The pack is 30p a can, so it is cheaper", "You can't work out a price per can"], why: "£3 ÷ 6 = 50p per can, which is more than 45p for a single can. Always check the unit price — multipacks aren't automatically better value." }
  ],

  // Borrowing & debt
  "mt_bAy4dmP1-A": [
    { q: "What does it mean to borrow money?", a: ["Use someone's money and pay it back later", "Get money as a gift that you never repay", "Earn money by doing a job", "Save money in a piggy bank"], why: "Borrowing means using money that belongs to someone else, such as a bank, and agreeing to pay it back — sometimes with extra charges." },
    { q: "Dan borrows £50 from his sister and agrees to repay £5 a week. How many weeks will it take him?", a: ["10 weeks", "5 weeks", "50 weeks", "15 weeks"], why: "£50 ÷ £5 = 10 weeks. Agreeing a clear repayment plan before borrowing helps you know you can pay it back." },
    { q: "When someone borrows from a bank, what decides whether they pay interest or fees?", a: ["The agreement they make with the lender", "Whatever they decide once they've spent it", "The colour of their bank card", "Nothing — borrowing is always free"], why: "Each loan or credit agreement sets out any interest and fees. Most lenders charge something, so it's important to read the terms before borrowing." },
    { q: "What is 'credit'?", a: ["Buying now and paying later: borrowing", "Money you have saved in your account", "A discount that shops give you", "Money you never have to pay back"], why: "Credit lets you have something now and pay for it later. It is a form of borrowing, so the money must be repaid, often with interest." },
    { q: "Which of these is usually the most sensible reason to borrow?", a: ["Buying a home, repaid over many years", "Buying a new phone every month", "A holiday you can't afford to repay", "Getting the latest trainers on credit"], why: "A mortgage helps people buy a home — something big and lasting that would take too long to save for. Borrowing for luxuries you can't afford is risky." },
    { q: "Why can having too much debt be risky?", a: ["Repayments can take too much of your money", "Debts disappear if you ignore them for long", "Bigger loans never charge any interest", "Borrowed money never needs to be paid back"], why: "Repayments must be made every month. If they're too big, there may not be enough left for bills and food, and missed payments can add extra charges." },
    { q: "What can happen if someone keeps missing their loan repayments?", a: ["Extra charges, and harder to borrow in future", "The loan is cancelled and soon forgotten about", "The bank pays them some of the money back", "Nothing happens, as long as they're polite"], why: "Missed payments can add late fees and more interest, and harm a person's credit record, so lenders may refuse to lend later. Getting help early matters." },
    { q: "A shop offers '0% interest — pay over 12 months' on a £240 bike. Which is true?", a: ["You must still repay the full £240", "The bike is free because there's no interest", "You only repay the interest, which is £0", "You can stop paying whenever you like"], why: "0% interest means no extra charge on top, but it's still borrowing: you must repay the £240 (here £20 a month). Missing a payment may cost extra." }
  ],

  // Interest rates and bank fees
  "mt_UXMNnis3v3": [
    { q: "You keep £100 in a savings account that pays interest. Who pays the interest?", a: ["The bank pays you", "You pay the bank", "Nobody pays anything", "The government pays you"], why: "On savings, the bank pays you interest for keeping your money with it. On loans and credit it's the other way round: you pay interest." },
    { q: "An account has a flat £2 monthly fee. Your balance grows from £100 to £500. What happens to the fee?", a: ["It stays at £2 a month", "It rises to £10 a month", "It falls to £1 a month", "It disappears completely"], why: "A flat fee is the same whatever the balance. Things worked out as a percentage, like interest, are what change when the balance changes." },
    { q: "An account charges a £2 monthly fee. How much will you pay in fees if you keep it for 6 months?", a: ["£12", "£2", "£8", "£6"], why: "A monthly fee is charged every month, so 6 months costs 6 × £2 = £12. Keeping an account longer adds more fees." },
    { q: "A savings account pays 3% per year. You keep £200 in it for one year. How much interest do you earn?", a: ["£6", "£3", "£60", "£0.60"], why: "3% means £3 for every £100. £200 is two lots of £100, so the interest is 2 × £3 = £6 for the year." },
    { q: "An account card says: 'Interest 2% per year. £1 for each cash withdrawal over 5 a month.' What kind of charge is the £1?", a: ["A charge per transaction", "A flat monthly account fee", "Interest charged on a loan", "Interest paid on savings"], why: "The £1 is charged for each extra withdrawal, so it depends on how many transactions you make — it isn't a fixed monthly amount." },
    { q: "Card A charges interest of 2% per month. Card B charges 2% per year. For the same amount owed all year, which charges more?", a: ["Card A", "Card B", "They charge the same", "Neither charges interest"], why: "Card A charges 2% every month — twelve times a year — while B charges 2% once a year. Always check the period a rate applies to." },
    { q: "Account A pays 4% a year with no fees. Account B pays 5% a year but charges £1 a month. You save £100 for a year. Which leaves you better off?", a: ["Account A", "Account B", "They leave you equally well off", "Neither pays any interest"], why: "A: 4% of £100 = £4. B: 5% of £100 = £5, but 12 monthly fees of £1 cost £12, so you'd be £7 worse off. A higher rate isn't always better." },
    { q: "Loan X charges 8% per year. Loan Y charges 6% per year plus a £50 set-up fee. Why can't you pick the cheaper loan from the rates alone?", a: ["The fee also adds to the total cost", "A lower rate always means a lower cost", "Set-up fees are paid back to you later", "Every bank charges the same rates"], why: "The total cost depends on the rate, the amount, how long you borrow for and any fees. Rates and fees vary between lenders, so compare everything." }
  ],

  // Comparing ways to pay
  "mt_3BDMrubDH8": [
    { q: "When you pay with a debit card, where does the money come from?", a: ["Straight from your own bank account", "Money that the bank lends to you", "Out of the shop's own bank account", "From a separate gift card balance"], why: "A debit card takes money from your own bank account. A credit card is different: it is borrowing, so the bank pays and you repay it later." },
    { q: "Which is a disadvantage of paying with cash?", a: ["If you lose it, it's very hard to get back", "Every shop charges a fee for using it", "You need a phone signal to use it", "It takes days to reach the shop"], why: "Lost or stolen cash is usually gone for good. A lost card can be blocked by the bank, and money taken from it may be refunded." },
    { q: "Mia is buying a 50p drink at a small market stall that has no card reader. Which way to pay is most suitable?", a: ["Cash", "Credit card", "Debit card", "Contactless phone payment"], why: "Without a card reader, the stall can't take card or phone payments. Cash needs no equipment, so it's the simplest choice for a small purchase." },
    { q: "Which is true about paying with a credit card?", a: ["It's borrowing that must be paid back", "It uses money you've already saved", "It's free money from the bank", "It only works in cash machines"], why: "With a credit card the bank pays the shop and you owe the bank. If you don't repay in full by the due date, interest is usually charged." },
    { q: "Which way of paying makes it easiest to keep a record of what you spent?", a: ["Card or phone, shown on a statement", "Cash, because it leaves no record", "Cash, because coins show the year", "Any — they all keep the same record"], why: "Card and phone payments appear on a statement or in a banking app, showing where and when you paid. Cash leaves no record unless you keep receipts." },
    { q: "Ben has a £20 prepaid gift card for one online shop. What is a limitation of it?", a: ["It only works at that shop, up to £20", "It lets him borrow as much as he likes", "It works in every shop in the world", "He pays interest every time he uses it"], why: "A gift or prepaid card holds a set amount and is often limited to one shop. Once the £20 is used up, it can't pay for anything else." },
    { q: "Lily wants to buy a present online, keep track of her spending and not borrow money. Which way to pay fits best?", a: ["Her debit card", "Cash sent in the post", "A credit card", "A loan from a friend"], why: "A debit card works online, uses her own money (no borrowing) and shows up on her statement. Credit cards and loans are borrowing; cash can't be used online." },
    { q: "A bus fare is £2.50 in cash or £2.20 by contactless card. Zara takes the bus 10 times a week. How much does paying contactless save her each week?", a: ["£3", "30p", "£22", "£25"], why: "Each trip saves £2.50 − £2.20 = 30p. Over 10 trips that is 10 × 30p = £3. Stated charges can make one way to pay cheaper than another." }
  ],

  // Scams & online safety
  "mt_W5euSyU2sO": [
    { q: "A text says: 'You've WON a £500 voucher! Click this link in the next 10 minutes!' What should you do?", a: ["Don't click; show a trusted adult", "Click quickly before it runs out", "Reply with your address to claim it", "Forward it to all your friends"], why: "A surprise prize and a rush to act are classic scam signs. Don't click the link — show a trusted adult, who can help you report and delete it." },
    { q: "Which of these is a common warning sign of a scam message?", a: ["Pressure to act right now or lose out", "It's from your mum about tea time", "It's a school newsletter you expected", "It's a reminder for a club you go to"], why: "Scammers rush you so you don't stop and think. Other warning signs are asking for personal details and offers that seem too good to be true." },
    { q: "What does 'if it seems too good to be true, it probably is' mean?", a: ["Amazing offers are often scams, so take care", "Good things never happen to anyone online", "Always trust offers that look really great", "Offers from big brands are always genuine"], why: "A brand-new phone for £5 or a big prize you never entered are hooks that scammers use. A deal that's unusually good is a sign to stop and check." },
    { q: "An email says it's from your bank and asks you to 'confirm your password' using a link. What is this most likely to be?", a: ["A phishing scam", "A normal bank request", "A friendly reminder", "A prize notification"], why: "Banks never ask for your password by email. Messages that pretend to be from trusted organisations to steal details are called phishing." },
    { q: "Why should you never share your passwords or bank details in a message, even when asked nicely?", a: ["Someone could use them to take your money", "It makes the internet slower for everyone", "Passwords stop working once shared", "Your account is deleted straight away"], why: "With your password or bank details, a scammer could pretend to be you, take money or lock you out of accounts. Real banks never ask for your password." },
    { q: "A website selling very cheap trainers has a strange web address and lots of spelling mistakes. What should you think?", a: ["It could be fake — check with an adult", "It might be a bargain, so buy it fast", "Cheap prices prove it's a genuine sale", "Web addresses never really matter"], why: "Odd web addresses, poor spelling and prices that are far too low are signs of a fake shop. Don't type in any details — ask an adult to help check." },
    { q: "A message from a 'friend' in a game says: 'I'm stuck, send me your card number and I'll pay you back.' What is the safest response?", a: ["Don't send it; tell a trusted adult", "Send it — they're your friend", "Send just half of the card number", "Make them promise first, then send it"], why: "Accounts can be hacked, so the message may not be from your friend at all. Never send card details — tell a trusted adult, who can check and report it." },
    { q: "Kai says, 'This text must be real — it has the bank's logo and says it's from the bank.' What's his mistake?", a: ["Scammers can copy logos and sender names", "Real bank texts are always in capitals", "Banks only ever contact you by letter", "Nothing — a logo proves it's genuine"], why: "Logos and sender names are easy to copy. To check, contact the bank using a number you already trust — never one given in the message." }
  ]
});
